222	    /** Whether the membership's dates include the sheet's today. */
223	    private static boolean current(ResultSet rs, LocalDate today) throws SQLException {
224	        Date from = rs.getDate("from_date");
225	        Date to = rs.getDate("to_date");
226	        return (from == null || !from.toLocalDate().isAfter(today)) && (to == null || !to.toLocalDate().isBefore(today));
227	    }
228	
229	    /** The pool with its members' cuts, its pool above cut first. */
230	    private static Pool cutDown(String name, Map<String, Pool> pools, Map<String, String> parents, BigDecimal sheetPot,
231	            Set<Long> held, Map<String, Pool> done) {
232	        Pool known = done.get(name);
233	        if (known != null) {
234	            return known;
235	        }
236	        Pool pool = pools.get(name);
237	        BigDecimal pot = sheetPot;
238	        String parent = parents.get(name);
239	        if (parent != null && pools.containsKey(parent)) {
240	            pot = null;
241	            for (PoolMember m : cutDown(parent, pools, parents, sheetPot, held, done).members()) {
242	                if (name.equals(m.memberPool()) && !m.cut().isEmpty()) {
243	                    pot = new BigDecimal(m.cut());
244	                }
245	            }
246	        }
247	        Pool out = pool.balanced() && pot != null
248	                ? new Pool(name, cut(pool.members(), pot, held), pool.totalShare(), true)
249	                : pool;
250	        done.put(name, out);
251	        return out;
252	    }
253	
254	    /**
255	     * The members each with their cut of the pot: the pot times their share over the shares of the members with a cut
256	     * (neither retired nor held), half to even to two decimals (a retired or held member's 0.00); the remainder, the
257	     * pot less the cuts, goes to the member with the smallest non-zero cut, the latest added on a tie (or, when no
258	     * cut is non-zero, to the last member with a cut and a share), so the cuts total the pot (each 0.00 when no member has a cut). A pool whose every member within their dates is retired
259	     * shows no cuts.
260	     */
261	    private static List<PoolMember> cut(List<PoolMember> members, BigDecimal pot, Set<Long> held) {
262	        if (members.stream().filter(PoolMember::current).allMatch(PoolMember::retired)) {
263	            return members;
264	        }
265	        BigDecimal shares = BigDecimal.ZERO.setScale(2);
266	        for (PoolMember m : members) {
267	            if (hasCut(m, held)) {
268	                shares = shares.add(new BigDecimal(m.share()));
269	            }
270	        }
271	        List<BigDecimal> cuts = new ArrayList<>();
272	        BigDecimal sum = BigDecimal.ZERO.setScale(2);
273	        for (PoolMember m : members) {
274	            BigDecimal cut = hasCut(m, held) && shares.signum() > 0
275	                    ? pot.multiply(new BigDecimal(m.share())).divide(shares, 2, RoundingMode.HALF_EVEN)
276	                    : BigDecimal.ZERO.setScale(2);
277	            cuts.add(cut);
278	            sum = sum.add(cut);
279	        }
280	        int smallest = -1;
281	        int lastShare = -1;
282	        for (int i = 0; i < members.size(); i++) {
283	            if (!hasCut(members.get(i), held)) {
284	                continue;
285	            }
286	            if (new BigDecimal(members.get(i).share()).signum() > 0) {
287	                lastShare = i;
288	            }
289	            BigDecimal cut = cuts.get(i);
290	            if (cut.signum() != 0 && (smallest < 0 || cut.compareTo(cuts.get(smallest)) <= 0)) {
291	                smallest = i;
292	            }
293	        }
294	        int takes = smallest >= 0 ? smallest : lastShare;
295	        if (takes >= 0 && shares.signum() > 0) {
296	            cuts.set(takes, cuts.get(takes).add(pot.subtract(sum)));
297	        }
298	        List<PoolMember> out = new ArrayList<>();
299	        for (int i = 0; i < members.size(); i++) {
300	            PoolMember m = members.get(i);
301	            out.add(new PoolMember(m.person(), m.memberPool(), m.name(), m.share(), m.retired(), m.from(), m.to(),
302	                    m.current(), m.current() ? cuts.get(i).toPlainString() : "", m.cuts()));
303	        }
304	        return out;
305	    }
306	
307	    /** Whether the member takes a cut: within their membership dates, and a pool or a person neither retired nor held. */
308	    private static boolean hasCut(PoolMember m, Set<Long> held) {
309	        return m.current() && (m.memberPool() != null || !(m.retired() || held.contains(m.person())));
310	    }
311	
312	    /** Whether the sheet has a pool of this name, one added or a crew. */
313	    public boolean has(String sheet, String name) {
314	        return hasAdded(sheet, name) || isCrew(sheet, name);
315	    }
316	
317	    /** Whether the sheet has a pool of this name that was added as a pool (not a crew). */
318	    public boolean hasAdded(String sheet, String name) {
319	        Integer found = jdbc.queryForObject("SELECT COUNT(*) FROM pool WHERE sheet = ? AND name = ?", Integer.class,
320	                sheet, name);
321	        return found != null && found > 0;
322	    }
323	
324	    /** Whether the pool of this name is a crew, its members the crew's. */
325	    public boolean isCrew(String sheet, String name) {
326	        Integer found = jdbc.queryForObject("SELECT COUNT(*) FROM crew WHERE sheet = ? AND name = ?", Integer.class,
327	                sheet, name);
328	        return found != null && found > 0;
329	    }
330	
331	    /** Whether the person is in the pool. */
332	    public boolean isMember(String sheet, String pool, long person) {
333	        Integer found = jdbc.queryForObject(
334	                "SELECT COUNT(*) FROM pool_member WHERE sheet = ? AND pool = ? AND person_id = ?", Integer.class, sheet,
335	                pool, person);
336	        return found != null && found > 0;
337	    }
338	
339	    /** The pool this pool is a member of, or null. */
340	    public String parentOf(String sheet, String pool) {
341	        List<String> found = jdbc.queryForList("SELECT pool FROM pool_sub WHERE sheet = ? AND member = ?",
342	                String.class, sheet, pool);
343	        return found.isEmpty() ? null : found.get(0);
344	    }
345	
346	    /** The pools that are members of this pool. */
347	    public List<String> subPools(String sheet, String pool) {
348	        return jdbc.queryForList("SELECT member FROM pool_sub WHERE sheet = ? AND pool = ?", String.class, sheet,
349	                pool);
350	    }
351	
352	    public void add(String sheet, String name) {
353	        jdbc.update("INSERT INTO pool (sheet, name, position, added_on) VALUES (?, ?,"
354	                + " (SELECT COALESCE(MAX(p.position), 0) + 1 FROM pool p WHERE p.sheet = ?), ?)", sheet, name, sheet,
355	                Date.valueOf(clock.today(sheet)));
356	    }
357	
358	    public void addMember(String sheet, String pool, long person, BigDecimal share, LocalDate from, LocalDate to) {
359	        jdbc.update("INSERT INTO pool_member (sheet, pool, person_id, share, from_date, to_date, position, added_on)"
360	                + " VALUES (?, ?, ?, ?, ?, ?, " + NEXT_MEMBER + ", ?)", sheet, pool, person, share, sqlDate(from),
361	                sqlDate(to), sheet, sheet, Date.valueOf(clock.today(sheet)));
362	    }
363	
364	    public void addSubPool(String sheet, String pool, String member, BigDecimal share, LocalDate from, LocalDate to) {
365	        jdbc.update("INSERT INTO pool_sub (sheet, pool, member, share, from_date, to_date, position, added_on)"
366	                + " VALUES (?, ?, ?, ?, ?, ?, " + NEXT_MEMBER + ", ?)", sheet, pool, member, share, sqlDate(from),
367	                sqlDate(to), sheet, sheet, Date.valueOf(clock.today(sheet)));
368	    }
369	
370	    private static Date sqlDate(LocalDate date) {
371	        return date == null ? null : Date.valueOf(date);
372	    }
373	
374	    /** The next position among all pools' members, people and pools. */
375	    private static final String NEXT_MEMBER = "(SELECT COALESCE(MAX(x.position), 0) + 1 FROM (SELECT position FROM"
376	            + " pool_member WHERE sheet = ? UNION ALL SELECT position FROM pool_sub WHERE sheet = ?) x)";
377	}
