387	 * that counted at the end of its last day (OPEN, PENDING and SETTLED then by their status log, but not a deferred one, nor an unbound open one dated
388	 * within its person's hold) (a
389	 * claim with no rate adds nothing). Refuses a role the permission matrix does not let close, a period not on the sheet or one already closed.
390	 */
391	public class ClosePeriod {
392	    public void close(@PathVariable("sheet") String sheet, @PathVariable("period") String period,
393	            @RequestParam("user") String user, Periods periods, PeriodCloser closer, Settings settings,
394	            Roles roles)
395	            throws InvalidPeriodException {
