400	        if (found == null) {
401	            throw new InvalidPeriodException("There is no period named " + period);
402	        }
403	        if (found.closed()) {
404	            throw new InvalidPeriodException("The period " + period + " is already closed");
405	        }
406	        if (!closer.close(sheet, user, found, false)) {
407	            throw new InvalidPeriodException("The period " + period + " is already closed");
408	        }
409	    }
410	}
