448	/**
449	 * Reopens a closed or soft-closed period: its fixed due-total is dropped, so it totals its claims' current figures again. Only a
450	 * role the permission matrix lets (by default a steward) may; refuses anyone else, a period not on the sheet, one locked, or one not closed.
451	 */
452	public class ReopenPeriod {
453	    public void reopen(@PathVariable("sheet") String sheet, @PathVariable("period") String period,
454	            @RequestParam("user") String user, Periods periods, Roles roles, Settings settings, Audit audit)
455	            throws InvalidPeriodException {
456	        if (!settings.permits(sheet, "reopen", roles.of(sheet, user))) {
457	            throw new InvalidPeriodException("Your role may not reopen a period");
458	        }
459	        Period found = periods.find(sheet, period);
460	        if (found == null) {
461	            throw new InvalidPeriodException("There is no period named " + period);
462	        }
463	        if (found.locked()) {
464	            throw new InvalidPeriodException("The period " + period + " is locked");
465	        }
466	        if (!found.fixed() || !periods.reopen(sheet, period)) {
467	            throw new InvalidPeriodException("The period " + period + " is not closed");
