472	package net.officefloor.hq.app.period;
473	
474	import java.math.BigDecimal;
475	import java.time.LocalDate;
476	import java.util.Comparator;
477	import java.util.LinkedHashMap;
478	import java.util.List;
479	import java.util.Map;
480	import java.util.stream.Collectors;
481	import net.officefloor.hq.app.Audit;
482	import net.officefloor.hq.app.claim.Claim;
483	import net.officefloor.hq.app.claim.ClaimStatus;
484	import net.officefloor.hq.app.claim.Claims;
485	import net.officefloor.hq.app.claim.Late;
486	import net.officefloor.hq.app.person.People;
487	import net.officefloor.hq.app.person.Person;
488	import net.officefloor.hq.app.rate.Rate;
489	import net.officefloor.hq.app.rate.Rates;
490	import net.officefloor.hq.app.setting.Dated;
491	import net.officefloor.hq.app.setting.Settings;
492	import net.officefloor.hq.app.sheet.SheetClock;
493	import org.springframework.stereotype.Service;
494	
495	/**
496	 * Closes a period, fixing its due-total now, and each person's on the sheet (the part of it from their claims): the due now of the claims whose due-by falls in it
497	 * that counted at the end of its last day (OPEN, PENDING and SETTLED then by their status log, but not a deferred one, nor an unbound open one dated
498	 * within its person's hold) (a claim with no rate adds nothing); and each person's carried figure for it: the due now of
499	 * their claims that count at its end whose due-by falls in an earlier period (one ending before it starts) and that were
500	 * still OPEN or PENDING at its end by their status log, plus their opening balance for it. Shared by a close by hand and the auto close of a today change.
501	 */
502	@Service
503	public class PeriodCloser {
504	
505	    private final Periods periods;
506	    private final Claims claims;
507	    private final People people;
508	    private final Rates rates;
509	    private final Settings settings;
510	    private final SheetClock clock;
511	    private final Audit audit;
512	
513	    public PeriodCloser(Periods periods, Claims claims, People people, Rates rates, Settings settings, SheetClock clock,
514	            Audit audit) {
515	        this.periods = periods;
516	        this.claims = claims;
517	        this.people = people;
518	        this.rates = rates;
519	        this.settings = settings;
520	        this.clock = clock;
521	        this.audit = audit;
522	    }
523	
524	    /** Closes the period found open on the sheet; false when it was already closed. An auto close is audited auto=yes. */
525	    public boolean close(String sheet, String user, Period found, boolean auto) {
526	        return close(sheet, user, found, auto, false);
527	    }
528	
529	    /**
530	     * Closes the period found open (or soft-closed) on the sheet, or soft-closes it, fixing its figures afresh; false
531	     * when it was already closed, or for a soft close already soft-closed.
532	     */
533	    public boolean close(String sheet, String user, Period found, boolean auto, boolean soft) {
534	        LocalDate from = LocalDate.parse(found.from());
535	        LocalDate to = LocalDate.parse(found.to());
536	        Map<Long, Person> byId = people.list(sheet).stream().collect(Collectors.toMap(Person::id, (p) -> p));
537	        List<Rate> sheetRates = rates.list(sheet);
538	        Dated floor = settings.floor(sheet);
539	        Late late = settings.late(sheet, clock.today(sheet));
540	        BigDecimal total = BigDecimal.ZERO.setScale(2);
541	        Map<Long, BigDecimal> perPerson = new LinkedHashMap<>();
542	        byId.keySet().forEach((id) -> perPerson.put(id, BigDecimal.ZERO.setScale(2)));
543	        Map<Long, BigDecimal> carried = new LinkedHashMap<>(perPerson);
544	        periods.openings(sheet, found.name()).forEach((id, amount) -> {
545	            if (carried.containsKey(id)) {
546	                carried.merge(id, amount, BigDecimal::add);
547	            }
548	        });
549	        List<Period> sheetPeriods = periods.list(sheet);
550	        List<Claim> sheetClaims = claims.list(sheet);
551	        for (Claim claim : sheetClaims) {
552	            Person person = byId.get(claim.person());
553	            LocalDate dueBy = LocalDate.parse(claim.dueBy());
554	            boolean earlier = sheetPeriods.stream().anyMatch((p) -> !dueBy.isBefore(LocalDate.parse(p.from()))
555	                    && !dueBy.isAfter(LocalDate.parse(p.to())) && LocalDate.parse(p.to()).isBefore(from));
556	            ClaimStatus then = claim.statusOn(to);
557	            if (person == null || !earlier || (then != ClaimStatus.OPEN && then != ClaimStatus.PENDING)
558	                    || !person.countsOn(claim, to)) {
559	                continue;
560	            }
561	            BigDecimal due = claim.due(sheetRates, person.gradeOn(claim.date()), floor, late);
562	            if (due != null) {
563	                carried.merge(person.id(), due, BigDecimal::add);
564	            }
565	        }
566	        for (Claim claim : sheetClaims) {
567	            LocalDate date = LocalDate.parse(claim.dueBy());
568	            Person person = byId.get(claim.person());
569	            if (person == null || !person.countsOn(claim, to) || date.isBefore(from) || date.isAfter(to)) {
570	                continue;
571	            }
572	            BigDecimal due = claim.due(sheetRates, person.gradeOn(claim.date()), floor, late);
573	            if (due != null) {
574	                total = total.add(due);
575	                perPerson.merge(person.id(), due, BigDecimal::add);
576	            }
577	        }
578	        if (!periods.close(sheet, found.name(), total, perPerson, carried, soft)) {
579	            return false;
580	        }
581	        audit.record((soft ? "PERIOD_SOFT_CLOSED" : "PERIOD_CLOSED") + " sheet=" + sheet + " by=" + user + " period=" + found.name() + " total="
582	                + total.toPlainString() + (auto ? " auto=yes" : ""));
583	        return true;
584	    }
585	
586	    /**
587	     * Closes, in order of their to-dates, every open (neither closed nor soft-closed) period of the sheet whose to-date plus the grace days is before
588	     * the sheet's today; none when the sheet has no grace days.
589	     */
590	    public void autoClose(String sheet, String user) {
591	        Integer grace = settings.graceDays(sheet);
592	        if (grace == null) {
593	            return;
594	        }
595	        LocalDate today = clock.today(sheet);
596	        List<Period> due = periods.list(sheet).stream()
597	                .filter((p) -> !p.fixed() && LocalDate.parse(p.to()).plusDays(grace).isBefore(today))
598	                .sorted(Comparator.comparing(Period::to)).toList();
599	        for (Period period : due) {
600	            close(sheet, user, period, true);
601	        }
602	    }
603	}
