    /**
     * Closes the period (or soft-closes it) with its due-total and each person's due-total and carried figure (by id)
     * fixed afresh; false when it was
     * already closed, or for a soft close already soft-closed (or is gone). Closing a soft-closed period is allowed.
     */
    public boolean close(String sheet, String name, BigDecimal total, Map<Long, BigDecimal> people,
            Map<Long, BigDecimal> carried, boolean soft) {
        String sql = soft
                ? "UPDATE period SET soft = TRUE, closed_total = ? WHERE sheet = ? AND name = ? AND NOT closed AND NOT soft"
                : "UPDATE period SET closed = TRUE, soft = FALSE, closed_total = ? WHERE sheet = ? AND name = ? AND NOT closed";
        if (jdbc.update(sql, total, sheet, name) != 1) {
            return false;
        }
        jdbc.update("DELETE FROM period_person_total WHERE sheet = ? AND period = ?", sheet, name);
        people.forEach((person, due) -> jdbc.update(
                "INSERT INTO period_person_total (sheet, period, person, total, carried) VALUES (?, ?, ?, ?, ?)", sheet,
                name, person, due, carried.getOrDefault(person, BigDecimal.ZERO.setScale(2))));
        return true;
    }

    /** Reopens the closed or soft-closed period, dropping its fixed due-totals and carried figures; false when it was neither, is locked (or is gone). */
    public boolean reopen(String sheet, String name) {
        if (jdbc.update("UPDATE period SET closed = FALSE, soft = FALSE, closed_total = NULL WHERE sheet = ? AND name = ?"
                + " AND (closed OR soft) AND NOT locked",
                sheet, name) != 1) {
            return false;
        }
        jdbc.update("DELETE FROM period_person_total WHERE sheet = ? AND period = ?", sheet, name);
        return true;
    }

    /** Locks or unlocks the period; false when it already was (or is gone). */
    public boolean lock(String sheet, String name, boolean locked) {
        return jdbc.update("UPDATE period SET locked = ? WHERE sheet = ? AND name = ? AND locked <> ?", locked, sheet,
                name, locked) == 1;
    }
package net.officefloor.hq.app.pool;

import java.util.Map;

/**
 * A member of a pool with their share percent (two decimals): a person (memberPool null), retired when the person has
 * a retirement date set, or another pool (memberPool its name, person 0, never retired); the membership's from-date and
 * to-date ("" when none) and whether they include the sheet's today (a member outside them is left out entirely); and
 * their cut of the pool's pot (two decimals), or "" when the pool is not balanced or has no pot, or the member is
 * outside their dates; and, by the name of every period whose to-date is on or before the sheet's today, their cut as
 * it stood at the end of that period (the pool, its members, the pot and the holds as they were then, with that day as
 * the sheet's today), "" when there was none.
 */
public record PoolMember(long person, String memberPool, String name, String share, boolean retired, String from,
        String to, boolean current, String cut, Map<String, String> cuts) {

    public PoolMember(long person, String memberPool, String name, String share, boolean retired, String from,
            String to, boolean current, String cut) {
        this(person, memberPool, name, share, retired, from, to, current, cut, Map.of());
    }

    /** Who the member is within its pool: the person's id, or pool:<name>. */
    public String key() {
        return memberPool != null ? "pool:" + memberPool : String.valueOf(person);
    }
}
-- A closed or soft-closed period's carried figure per person, fixed with their due-total when it was (soft-)closed;
-- reopening the period drops it with the row.
ALTER TABLE period_person_total ADD COLUMN carried DECIMAL(15, 2) NOT NULL DEFAULT 0;

